/* @lc app=leetcode id=3389 lang=kotlin */ class Solution { fun b(x: Int, fin: Int): Int = maxOf(0, x - fin) + maxOf(0, fin - x) fun makeStringGood(s: String): Int = s.toList().groupingBy { it }.eachCount().let { m -> ('a'..'z').map { m[it] ?: 0 }.let { c -> (1..c.max()).minOf { f -> (1..25).fold(listOf(b(c[0], 0), b(c[0], f))) { dp, i -> List(2) { cc -> (0..1).minOf { cp -> dp[cp] + b(c[i], cc * f) - minOf(maxOf(0, c[i - 1] - cp * f), maxOf(0, cc * f - c[i])) } } }.min() } } } }